import{_ as t,o as r,c as e,X as a}from"./chunks/framework.92e7fb7b.js";const m=JSON.parse('{"title":"最近一份工作的难点","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/fe-sumary/xz-fe.md","filePath":"blogs/fe-sumary/xz-fe.md"}'),i={name:"blogs/fe-sumary/xz-fe.md"},l=a('<h1 id="最近一份工作的难点" tabindex="-1">最近一份工作的难点 <a class="header-anchor" href="#最近一份工作的难点" aria-label="Permalink to &quot;最近一份工作的难点&quot;">​</a></h1><h2 id="seo、服务端渲染" tabindex="-1">seo、服务端渲染 <a class="header-anchor" href="#seo、服务端渲染" aria-label="Permalink to &quot;seo、服务端渲染&quot;">​</a></h2><table><thead><tr><th><div style="width:30px;"></div></th><th>Description</th></tr></thead><tbody><tr><td>背景</td><td>计划全站SEO、工期紧 一期迭代要求一周</td></tr><tr><td>难点</td><td>1. 原单页面改全站SEO <br><br> 2. 主子页面登录态共享</td></tr><tr><td>选型</td><td>1. session方案<br><br>2. vue2-》nuxt2 cv简单修改即可，落地快，团队成员好上手</td></tr><tr><td>落地</td><td>1. SEO不收录问题解决，主动提交 sitemap、robots正确配置、footer link标签、增加内链与外链 <br><br> 2. 收录meta方式无法收录（因为meta多了data-属性），域名下放认证文件的模式 <br><br> 3. 用户反馈登录态过期，实际上www.abc.com访问和abc.com存的cookie domain分别是.abc.com 和abc.com 不一致导致的；</td></tr><tr><td>总结</td><td>1. 如果是不同的子域名，使用oauth2 做登录态共享 <br><br> 2. 服务端请求中访问vue实例（nuxt2不可行，服务端钩子中组件没有实例化 还拿不到组件上面的方法） <br><br> 3. 语义化标签</td></tr></tbody></table><h2 id="微前端" tabindex="-1">微前端 <a class="header-anchor" href="#微前端" aria-label="Permalink to &quot;微前端&quot;">​</a></h2><table><thead><tr><th><div style="width:30px;"></div></th><th>Description</th></tr></thead><tbody><tr><td>背景</td><td>业务要新开一个saas系统，后续可能做paas，子系统多根据用户开通情况分配权限</td></tr><tr><td>难点</td><td>1. 子系统用户权限（页面路由、数据权限）设计<br><br>2. 多子系统共用组件库 共享依赖（全局组件库）<br><br>3. css隔离 样式隔离</td></tr><tr><td>选型</td><td>1.RBAC or RBAC1(角色继承)省空间 <br><br>2.制定路由规范 一级规定指向应用 主应用控制应用进入的权限、子应用内路由首位使用基座的共享方法去控制具体页面的路由权限<br><br> 3. 公共组件库: 主应用分发 or 构建组件库 <br><br>4.qiankun、webcomponent方案（京东的）、iframe方案、路由方案,用微前端分目的是分割功能单元、精简代码库、控制发版单元、长期可迭代、技术无关性</td></tr><tr><td>落地</td><td>1. vue2 vue3 history控制权冲突； <br><br>2. 同时有两个实例时，弹窗应用使用虚拟路由 <br><br>3. 部署 运维用k8s不熟 混淆了redirect与tryfiles ,<br><br> 4. vue2 element冲突主应用 elemtnplus，基座影响子应用；解决方式是对子应用postcss、依赖包处理增加prevfix处理，也可以主应用本身cs也用打包工具处理 加scoped或者前缀<br><br> 5. 发版时已经加载的页面，加载了过期的已加载js，请求了chunk中过期的异步加载css（页面级别）导致的样式错乱问题（loader捕捉css加载的err）（ps：运维手段是立即删除所有旧的资源）</td></tr><tr><td>总结</td><td>1. cdn共享组件库优化 <br><br> 2. 多tab场景下vnode缓存TODO</td></tr><tr><td>思考</td><td>1. 如果跨域子域名加载怎么做？ <br><br> 2. RBAC RBAC1表设计，几张表，作用是什么，关联关系是什么<br><br> 3. k8s启动一个pod cicd配置流程</td></tr></tbody></table><hr><h2 id="虚拟列表-性能优化" tabindex="-1">虚拟列表 性能优化 <a class="header-anchor" href="#虚拟列表-性能优化" aria-label="Permalink to &quot;虚拟列表 性能优化&quot;">​</a></h2><ul><li>列表方案 不定高度？（从下往上滑动 页面抖动、删除节点页面跳动）</li></ul><p>复杂业务代码改造，（item 处理为计算属性）</p><p>一些个人的经验 关于虚拟列表相关的优化它真的就只是在优化 直接限制你每次滚动的范围，就类似之前看到大屏做上下幻灯片滚动一样，你滚动一下就滚动了整个屏幕，可以观察小红书（限制了只能滚动 没有滚动条）、微博</p><ul><li>从上往下时，nextTick中节点渲染好了就把container高度固定死</li><li>滑动过快到底部往上走、高度跳变、白屏问题 <ul><li>小红书的瀑布流虚拟列表，直接把滚动条隐藏了，只能滑轮滚，并且后端接口数据中直接返回图片的宽高。</li><li>pc端的微博，刷的过快它一定会先白屏之后再出现内容。其次就是像腾讯会议里回放的文本记录，每段文本记录都是item，但是因为它的高度差不是说特别大，而且是纯文本，这个问题就基本不存在。</li></ul></li></ul><h2 id="动画、多页面响应式适配、i18n" tabindex="-1">动画、多页面响应式适配、i18n <a class="header-anchor" href="#动画、多页面响应式适配、i18n" aria-label="Permalink to &quot;动画、多页面响应式适配、i18n&quot;">​</a></h2><ul><li><p>动态rem；</p></li><li><p>所有图片加载完成之后进入页面 i18n</p></li></ul><p>总结： rem有局限性吗？ TODO</p><h2 id="小程序路由权限校验" tabindex="-1">小程序路由权限校验 <a class="header-anchor" href="#小程序路由权限校验" aria-label="Permalink to &quot;小程序路由权限校验&quot;">​</a></h2><ul><li><p>首页路由切换闪烁</p></li><li><p>公共组件库处理 二次封装组件；支持透传slot attrs props等（原生组件有坑）</p></li></ul><h2 id="weboffice定制功能" tabindex="-1">weboffice定制功能 <a class="header-anchor" href="#weboffice定制功能" aria-label="Permalink to &quot;weboffice定制功能&quot;">​</a></h2><ul><li>只允许排版功能 <ul><li><p>iframe 限制</p><ul><li>electron <ul><li>太生硬 用户接受程度</li></ul></li><li>chrome插件 <ul><li>分发问题 - 谷歌市场上架</li></ul></li></ul></li><li><p>onlyoffice</p><ul><li>排版可能存在与wps不一致问题</li></ul></li></ul></li></ul>',18),d=[l];function o(s,b,c,n,h,u){return r(),e("div",null,d)}const f=t(i,[["render",o]]);export{m as __pageData,f as default};
